import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { gunzipSync } from "node:zlib";
import { API } from "typescript/unstable/sync";
import { createVirtualFileSystem } from "typescript/unstable/fs";
import * as ast from "typescript/unstable/ast";
import { transformSync } from "esbuild";
import { z } from "zod";
import { stateSchema } from "../../packages/core/src/model.js";
// Fixed historical test evidence only. Current contracts never read this archive.
// Exact actual-Git sources; generated JS changes only import wiring/meta URL.
const encoded =
  "";
export type ArchivedSource = {
  git: string;
  path: string;
  bytes: number;
  sha256: string;
  raw: string;
};
export const objectGovernanceHistory = JSON.parse(
  gunzipSync(Buffer.from(encoded, "base64")).toString(),
) as {
  sources: Record<string, ArchivedSource>;
  subjectAppExpected: Omit<ArchivedSource, "raw">;
};
for (const value of Object.values(objectGovernanceHistory.sources)) {
  assert.equal(Buffer.byteLength(value.raw), value.bytes);
  assert.equal(
    createHash("sha256").update(value.raw).digest("hex"),
    value.sha256,
  );
}
// This closed historical oracle has four fixed modules, not a current loader.
function run(
  key: string,
  bindings: Record<string, unknown>,
): Record<string, unknown> {
  const module = { exports: {} };
  const source = objectGovernanceHistory.sources[key]!;
  const code = transformSync(source.raw, {
    loader: "ts",
    format: "cjs",
    target: "es2022",
    define: {
      "import.meta.url": JSON.stringify(
        "file:///fixed-history/application/" + source.path,
      ),
    },
  }).code;
  new Function("require", "module", code)((name: string) => {
    assert.ok(
      Object.hasOwn(bindings, name),
      "only explicit historical dependency " + name,
    );
    return bindings[name];
  }, module);
  return module.exports;
}
const shared = {
  "node:assert/strict": assert,
  "node:crypto": { createHash },
  "typescript/unstable/sync": { API },
  "typescript/unstable/fs": { createVirtualFileSystem },
  "typescript/unstable/ast": ast,
};
const fixed = run("fixedObject", {
  zod: { z },
  "../../packages/core/src/model.js": { stateSchema },
});
const parser = run("readerParser", shared);
const peer = run("objectPeer", {
  ...shared,
  "./reader-reads-contract.js": parser,
  "./object-interactions-original.js": fixed,
  "node:fs": {
    readFileSync(url: URL) {
      assert.equal(
        url.pathname,
        "/fixed-history/application/apps/web/src/data/operation-delivery.ts",
        "one frozen operation operand",
      );
      return objectGovernanceHistory.sources.operation!.raw;
    },
  },
});
// Actual original reference inverse's first early-return branch only. The fixed
// Stage29 App has neither Stage30 registration; this is not the full peer oracle.
const reference = {
  inverseExchangeReferencePreparationApp(text: string) {
    assert.ok(
      !text.includes("useExchangeQuoteRevealState") &&
        !text.includes("useExchangeQuoteRevealCommit"),
      "fixed pre-Stage30 reference lane",
    );
    return text;
  },
};
export const historicalObjectAnnotations = run("objectHelper", {
  ...shared,
  "./exchange-reference-preparation-consumption.js": reference,
  "./object-interactions-consumption.js": {
    ...peer,
    readObjectInteractionOwner: () =>
      objectGovernanceHistory.sources.objectOwner!.raw,
  },
  "node:fs": {
    readFileSync(url: URL) {
      const key = url.pathname.endsWith(
        "/features/content/ObjectAnnotations.tsx",
      )
        ? "feature"
        : url.pathname.endsWith("/client.ts")
          ? "client"
          : undefined;
      assert.ok(key, "only fixed annotation default operands");
      return objectGovernanceHistory.sources[key]!.raw;
    },
  },
}) as Pick<
  typeof import("./object-annotations-consumption.js"),
  "assertObjectAnnotationsWholeApp" | "inverseObjectAnnotationsFeature"
>;
export const historicalSubjectApp =
  historicalObjectAnnotations.assertObjectAnnotationsWholeApp!(
    objectGovernanceHistory.sources.app!.raw,
    objectGovernanceHistory.sources.feature!.raw,
    objectGovernanceHistory.sources.client!.raw,
    objectGovernanceHistory.sources.objectOwner!.raw,
  ) as string;
assert.equal(
  Buffer.byteLength(historicalSubjectApp),
  objectGovernanceHistory.subjectAppExpected.bytes,
);
assert.equal(
  createHash("sha256").update(historicalSubjectApp).digest("hex"),
  objectGovernanceHistory.subjectAppExpected.sha256,
);
